    output  logic [2:0]  chargen_axi_arprot,
    output  logic [3:0]  chargen_axi_arqos,
    output  logic [3:0]  chargen_axi_arregion,
    output  logic         chargen_axi_aruser,
    output  logic         chargen_axi_arvalid,
